import {api,cleanEpisodes,quality,csv} from './data.js';
import {introduction,investigations} from './content.js';
import {readProgress,writeProgress} from './storage.js';
import {initialize,execute} from './runtime.js';
import {download,missingFields,makeArchive} from './export.js';
import {newState,newInvestigations,restoreState,initializeCustom,recordResult,finalVersion,requiredAnswers,answerMissing} from './state.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Introduction','Choose Show','Ratings','Trends','Storylines','Finish'];
let state=newState(),runtime='idle',runtimeMessage='Choose a show to start R.',busy=false,saveTimer,saveQueue=Promise.resolve(),customObserver;
function save(){clearTimeout(saveTimer);$('#save-status').textContent='Saving…';saveTimer=setTimeout(flush,250);}
function flush(){clearTimeout(saveTimer);const snapshot=structuredClone(state);saveQueue=saveQueue.catch(()=>{}).then(()=>writeProgress(snapshot)).then(()=>{$('#save-status').textContent='Progress saved in this browser';}).catch(()=>{$('#save-status').textContent='Could not save locally. Keep this tab open and download your work.';});return saveQueue;}
function go(step){if(busy)return;state.step=step;save();render();$('#main').focus();window.scrollTo(0,0);}
function render(){
 customObserver?.disconnect();
 $('#steps').innerHTML=names.map((name,i)=>`<button data-step="${i}" ${state.step===i?'aria-current="step"':''}>${name}</button>`).join('');
 document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(Number(b.dataset.step)));
 $('#show-label').textContent=state.show?`Selected show: ${state.show.name}`:'';
 $('#brand').onclick=e=>{e.preventDefault();go(0);};
 if(state.step===0)renderIntroduction();else if(state.step===1)renderChoose();else if(state.step===5)renderFinish();else renderLesson(state.step-2);
}
function table(rows){return `<div class="table-wrap"><table class="reference"><thead><tr><th scope="col">Feature</th><th scope="col">Example argument</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${escape(a)}</td><td><code>${escape(b)}</code></td></tr>`).join('')}</tbody></table></div>`;}
function renderIntroduction(){
    $('#main').innerHTML = `<section class="banner intro-banner"><h1>R You Watching?</h1><p>${introduction.subtitle}</p></section><div class="intro-copy">${state.legacyNotice ? '<p class="notice">Your previously saved code and graphs are now in Part 1. Your code has not been changed. The questions and workflow have changed; review the new prompts. Your previous responses are also available under each investigation.</p>' : ''}<section class="editorial-section">${introduction.paragraphs.map(p => `<p>${p}</p>`).join('')}</section><section class="editorial-section"><h2>What you’ll do</h2><p>First, choose a television show that interests you. We’ll retrieve its episode data and help you check whether there’s enough information for your investigation.</p><p>Then you’ll create three graphs:</p><ol class="intro-graphs"><li><div><h3>Episode Ratings — Histogram</h3><p>Discover how the ratings of your show’s episodes are distributed.</p></div></li><li><div><h3>Ratings Over Time — Line Graph</h3><p>Investigate how episode ratings change across the series.</p></div></li><li><div><h3>Episode Storylines — Bar Graph</h3><p>Explore which characters, events, or themes appear in episode descriptions.</p></div></li></ol></section><section class="editorial-section"><h2>For each graph, you’ll:</h2><ol class="three-parts"><li><strong>Create it.</strong> Use R to make a graph of your show’s data.</li><li><strong>Make it yours.</strong> Experiment with colors, styles, titles, and other design choices.</li><li><strong>Interpret it.</strong> Look for patterns, surprises, or anything that stands out. Think about how the results compare with your own experiences and opinions about the show.</li></ol><p>You don’t have to agree with the ratings or the picture painted by the data! In fact, that’s part of what makes the investigation interesting.</p></section><section class="editorial-section"><h2>How this homework works</h2><p>You’ll write and run R code directly in this website, just like you did in the labs.</p><p>We’ll provide comments, reminders, and hints to help you. You’ll still write the R commands yourself.</p><p>Your progress is saved automatically in this browser, so you can return to your work later using the same browser and device.</p></section><section class="editorial-section"><h2>What you’ll turn in</h2><p>At the end, you’ll download a ZIP containing your completed homework PDF and three PNG graph images.</p><p>Extract the ZIP and <strong>submit the PDF to Canvas</strong>. Keep your graph images to reuse in your final project.</p></section><div class="nav-actions intro-next"><button class="primary" id="intro-next">Choose Your Show →</button></div></div>`;
 $('#intro-next').onclick=()=>go(1);
}
function renderChoose(){
 $('#main').innerHTML=`<section class="page-heading"><h1>Choose your show</h1><p>Search for a television show you’d like to investigate. It can be a favorite or something you’re simply curious about.</p></section><form id="search-form"><label for="search">Television show title</label><div class="search-row"><input id="search" type="search" placeholder="Try The Office, Friends, or Breaking Bad…" required maxlength="120"><button id="search-button">Search shows</button></div></form><div id="search-message" role="status"></div><div class="results" id="results"></div><div id="selected"></div><details><summary>Need a starting point? Or is TVmaze unavailable? Use the bundled example of The Office.</summary><p>The bundled snapshot of The Office (US) includes real episode ratings and summaries for all three investigations.</p><button id="example" class="secondary" type="button">Use The Office example</button></details><div class="nav-actions"><button id="back" class="secondary">← Introduction</button><button class="primary" id="begin" ${state.show?'':'disabled'}>Start Investigating →</button></div>`;
 $('#back').onclick=()=>go(0);$('#begin').onclick=()=>go(2);
 $('#search-form').onsubmit=async e=>{e.preventDefault();const q=$('#search').value.trim();if(!q)return;$('#search-button').disabled=true;$('#search-message').textContent='Searching TVmaze…';$('#results').innerHTML='';try{const results=await api('/search/shows?q='+encodeURIComponent(q));if(state.step!==1)return;$('#search-message').textContent=results.length?'Choose the version you mean.':'No matches. Try a shorter title or the bundled example.';for(const {show} of results){const el=document.createElement('article');el.className='result';el.dataset.showId=show.id;el.innerHTML=`<div class="result-info"><h3>${escape(show.name)}</h3><p>${escape(show.premiered?.slice(0,4)||'Year unknown')} · ${escape(show.network?.country?.name||show.webChannel?.country?.name||show.language||'Country unknown')}</p><p>${escape(show.network?.name||show.webChannel?.name||'Network unknown')} · ${escape(show.type)} · ${escape(show.status)}</p></div><button type="button">Select show</button>`;el.querySelector('button').onclick=()=>selectShow(show);$('#results').append(el);}}catch(e){if($('#search-message'))$('#search-message').innerHTML=`<p class="notice error">${escape(e.message)}</p>`;}finally{if($('#search-button'))$('#search-button').disabled=false;}};
 $('#example').onclick=async()=>{if(busy)return;try{const [show,episodes]=await Promise.all(['example-show','example-episodes'].map(x=>fetch(`./data/${x}.json`).then(r=>{if(!r.ok)throw Error('The example could not be loaded.');return r.json();})));if(state.step===1)await selectShow(show,episodes);}catch(e){if($('#search-message'))$('#search-message').textContent=e.message;}};
 selectedCard();
}
async function selectShow(show,raw){
 if(busy)return;
 if(runtime==='loading'){$('#search-message').textContent='R is still starting. Please wait before changing shows.';return;}
 if(state.show&&state.show.id!==show.id&&!confirm('Changing shows clears both versions of your graphs, their code, and your reflections. Download your current homework first if you want to keep it. Continue?'))return;
 busy=true;$('#search-message').textContent='Loading and preparing episodes…';
 try{
 const rows=cleanEpisodes(raw||await api(`/shows/${show.id}/episodes`));if(!rows.length)throw Error('This show has no aired regular episodes available. Please choose another show.');
 if(!state.show||state.show.id!==show.id){state.investigations=newInvestigations();state.workspace=null;delete state.legacyAnswers;delete state.legacyNotice;}
 if(state.show?.id!==show.id||!state.rows.length)state.rows=rows;
 state.show={id:show.id,name:show.name,url:show.url};state.retrieved=raw?'Bundled snapshot, November 6, 2026':new Date().toISOString().slice(0,10);save();$('#search-message').innerHTML=`<p class="notice selection-success">✓ You selected <strong>${escape(show.name)}</strong>. Your data is ready. Choose Start Investigating to continue.</p>`;document.querySelectorAll('.result').forEach(el=>{const selected=el.dataset.showId===String(show.id);el.classList.toggle('is-selected',selected);const button=el.querySelector('button');button.textContent=selected?'✓ Selected':'Select show';button.disabled=selected;});$('#show-label').textContent=`Selected show: ${show.name}`;selectedCard();$('#begin').disabled=false;$('#selected').scrollIntoView({block:'start'});$('#selection-heading').focus({preventScroll:true});
 }catch(e){$('#search-message').innerHTML=`<p class="notice error">${escape(e.message)}</p>`;}finally{busy=false;}
 if(state.show?.id===show.id)startR();
}
function selectedCard(){if(!state.show)return;const q=quality(state.rows);$('#selected').innerHTML=`<section class="selected-show"><h2 id="selection-heading" tabindex="-1">✓ Selected: ${escape(state.show.name)}</h2><p>Your show is selected and your data is ready. Choose <strong>Start Investigating</strong> to continue.</p><div class="stats">${[[q.total,'aired regular episodes'],[q.ratings,'episodes with ratings'],[q.summaries,'usable summaries'],[q.seasons,'seasons']].map(([n,t])=>`<div class="stat"><strong>${n}</strong>${t}</div>`).join('')}</div>${q.ratings<10||q.summaries<10?'<p class="notice warning">This show has fewer than 10 usable ratings or summaries. We recommend choosing another show for clearer patterns.</p>':''}<p class="small">Scripted shows are a useful starting point. TVmaze supplies average ratings, but no episode vote counts; some reality-show averages may reflect very few votes. Specials and unaired episodes are excluded.</p><button id="csv" class="secondary">Download Episode Data (CSV)</button><p class="small">Optional: keep a spreadsheet copy of your data. You do not need to submit it.</p></section>`;$('#csv').onclick=()=>download(new Blob([csv(state.rows)],{type:'text/csv;charset=utf-8'}),'episode_data.csv');}
async function startR(){if(runtime==='loading'||busy)return;runtime='loading';runtimeMessage='Starting R… the first load may take a minute.';refreshRuntime();try{await initialize(state.rows,state.workspace);runtime='ready';runtimeMessage='R is ready. Objects are shared between editors and saved after successful runs.';}catch(e){runtime='error';runtimeMessage='R could not start. Check your connection, then retry. '+e.message;}refreshRuntime();}
function refreshRuntime(){document.querySelectorAll('.runtime').forEach(el=>el.textContent=runtimeMessage);document.querySelectorAll('[data-run]').forEach(b=>b.disabled=runtime!=='ready'||busy);const retry=$('#retry');if(retry)retry.classList.toggle('hidden',runtime!=='error');}
function workspace(i,kind){const v=state.investigations[i][kind],label=kind==='basic'?'Basic':'Customized';return `<div class="workspace"><section class="editor-pane"><label for="editor-${kind}">${label} R editor — enter your code here</label><textarea id="editor-${kind}" class="editor" spellcheck="false" autocapitalize="off" autocomplete="off" aria-describedby="help-${kind}" placeholder="${kind==='custom'?'Your last successful basic graph code will be copied here when you begin.':''}"></textarea><p class="editor-help" id="help-${kind}">Ctrl/⌘ + Enter runs this editor. ${kind==='basic'?'Start with a working graph.':'Your basic code and saved graph stay unchanged.'}</p><div class="editor-controls"><button data-run="${kind}" id="run-${kind}">Run ${kind==='basic'?'Basic':'Customized'} R</button><button data-revert="${kind}" class="text-button ${v.graphCode?'':'hidden'}">Restore last successful ${kind==='basic'?'basic':'customized'} code</button></div><pre id="output-${kind}" class="output ${v.output?'':'hidden'}" aria-live="polite">${escape(v.output)}</pre></section><section class="graph-pane"><h3>${label} graph</h3><div class="graph" id="graph-${kind}">${graphMarkup(i,kind)}</div><p class="graph-note" id="note-${kind}">${graphNote(i,kind)}</p></section></div>`;}
function questionMarkup(q,answers){const help=q.help?`<p class="help" id="help-${q.id}">${escape(q.help)}</p>`:'';const reason=q.reason?`<label class="reason-label" for="answer-${q.id}Reason">${escape(q.reason)}</label><textarea id="answer-${q.id}Reason" data-answer="${q.id}Reason" maxlength="3000">${escape(answers[q.id+'Reason']||'')}</textarea>`:'';
 if(q.options)return `<fieldset class="question"><legend>${escape(q.label)}</legend>${help}${q.options.map((option,j)=>`<label class="radio-option" for="answer-${q.id}-${j}"><input type="radio" id="answer-${q.id}-${j}" name="${q.id}" data-answer="${q.id}" value="${escape(option)}" ${answers[q.id]===option?'checked':''}>${escape(option)}</label>`).join('')}${reason}</fieldset>`;
 return `<div class="question"><label for="answer-${q.id}">${escape(q.label)}</label>${help}<textarea id="answer-${q.id}" data-answer="${q.id}" ${q.help?`aria-describedby="help-${q.id}"`:''} maxlength="3000">${escape(answers[q.id]||'')}</textarea></div>`;
}
function guidanceMarkup(text){
 let html=escape(text);
 for(const sentence of ['Your data is saved in the variable rated_episodes.','Use the line_graph(data, x, y) helper function.'])html=html.replace(escape(sentence),`<strong class="instruction-emphasis">${escape(sentence)}</strong>`);
 return html;
}
function renderLesson(i){
 const l=investigations[i],item=state.investigations[i];
 if(!state.show){$('#main').innerHTML='<section class="page-heading"><h1>Choose a show first</h1><p>We’ll prepare the data and start R for you.</p><button class="primary" id="choose">Choose Your Show →</button></section>';$('#choose').onclick=()=>go(1);return;}
 $('#main').innerHTML=`<section class="banner"><h1>${l.title}</h1><p>${l.intro}</p></section><section class="part" id="create"><div class="part-heading"><span class="part-number">Part 1</span><h2>${l.createTitle}</h2></div><div class="guidance">${l.guidance.map(p=>`<p>${guidanceMarkup(p)}</p>`).join('')}<details><summary>Hints for your basic graph</summary><p>${escape(l.hint)}</p></details>${l.optional?`<details><summary>Optional: season averages for a long-running show</summary><p>${escape(l.optional)}</p></details>`:''}</div><div class="runtime-row"><span class="runtime" role="status"></span><button id="retry" class="secondary hidden">Retry starting R</button></div>${workspace(i,'basic')}</section><section class="part" id="customize"><div class="part-heading"><span class="part-number">Part 2</span><h2>Make it yours</h2></div><div class="custom-reference"><p>To customize your graph, add more arguments inside the function’s parentheses. Separate each argument with a comma. Your code may be easier to read and keep track of if you press Return after each comma instead of using only a space.</p><pre class="code-example">${escape(l.example)}</pre><p class="small">${escape(l.exampleNote)}</p><p><strong>Use at least five customization arguments in your graph.</strong> Experimenting matters more than making a beautiful graph. Choose a title that communicates something about your results.</p>${table(l.options)}<p class="small">${escape(l.customizationNote)}</p><p class="small">Explore <a href="https://stat.ethz.ch/R-manual/R-devel/library/grDevices/html/colors.html" target="_blank" rel="noreferrer">R’s named-color reference</a>, or run <code>colors()</code>.</p></div><div class="copy-row"><button class="text-button" id="copy-basic" ${item.basic.graphCode?'':'disabled'}>Copy basic code again</button><p id="copy-message" role="status">${item.custom.initialized?'The editors are independent. Copy again only if you want to start over.':'Your most recent successful basic graph code is copied when you begin here.'}</p></div>${workspace(i,'custom')}</section><section class="part" id="interpret"><div class="part-heading"><span class="part-number">Part 3</span><h2>${i===0?'Interpret your histogram':'Interpret your results'}</h2></div><p class="small">Keep each written response brief—a sentence or two is enough.</p>${l.interpretationNote?`<p class="small">${escape(l.interpretationNote)}</p>`:''}${l.questions.map(q=>questionMarkup(q,item.answers)).join('')}${state.legacyAnswers?.[i]?.some(Boolean)?`<details><summary>Your responses from the earlier assignment version</summary><p class="small">Saved for reference. Review the revised questions above before exporting.</p>${state.legacyAnswers[i].map((a,j)=>`<p><strong>Previous response ${j+1}:</strong> ${escape(a)}</p>`).join('')}</details>`:''}</section><div class="nav-actions"><button id="back" class="secondary">← ${names[i+1]}</button><button id="next" class="primary">${i===2?'Finish & Submit':names[i+3]} →</button></div>`;
 for(const kind of ['basic','custom']){
 const editor=$(`#editor-${kind}`);editor.value=item[kind].code;
 editor.onfocus=()=>{if(kind==='custom')beginCustom(i);};
 editor.oninput=e=>{item[kind].code=e.target.value;item[kind].initialized=true;save();$(`#note-${kind}`).textContent=graphNote(i,kind);};
 editor.onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();if(!$(`#run-${kind}`).disabled)run(i,kind);}};
 $(`#run-${kind}`).onclick=()=>run(i,kind);
 $(`[data-revert="${kind}"]`).onclick=()=>{if(confirm(`Replace this editor with the code that produced its last successful ${kind} graph?`)){item[kind].code=item[kind].graphCode;item[kind].initialized=true;editor.value=item[kind].code;save();$(`#note-${kind}`).textContent=graphNote(i,kind);}};
 }
 document.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{if(el.type==='radio'&&!el.checked)return;item.answers[el.dataset.answer]=el.value;save();});
 $('#copy-basic').onclick=()=>{if(busy)return;if(item.custom.initialized&&!confirm('Replace the customization editor with your last successful basic graph code? Your saved customized graph will remain until you create another successful graph.'))return;item.custom.code=item.basic.graphCode;item.custom.initialized=true;$('#editor-custom').value=item.custom.code;$('#copy-message').textContent='Basic code copied. The basic editor and graph are unchanged.';$('#note-custom').textContent=graphNote(i,'custom');save();};
 $('#retry').onclick=startR;$('#back').onclick=()=>go(i+1);$('#next').onclick=()=>go(i+3);refreshRuntime();
 customObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))beginCustom(i);},{threshold:.15});customObserver.observe($('#editor-custom'));
}
function beginCustom(i){if(initializeCustom(state.investigations[i])){$('#editor-custom').value=state.investigations[i].custom.code;$('#copy-message').textContent='Your successful basic graph code was copied. These editors are now independent.';save();}}
function graphMarkup(i,kind){const v=state.investigations[i][kind];return v.graph?`<img src="${v.graph}" alt="${kind==='basic'?'Basic':'Customized'} ${investigations[i].short.toLowerCase()} graph generated by R">`:`<div class="empty-graph">Run the ${kind==='basic'?'basic':'customization'} editor to see your graph here.</div>`;}
function graphNote(i,kind){const v=state.investigations[i][kind];return v.graph?(v.graphCode!==v.code?'This editor has changed since its graph was saved. Run it to update the graph.':'Your most recent successful graph for this editor is saved.'):'An error or a run without a graph will keep this editor’s last successful graph.';}
async function run(i,kind){
 if(busy||runtime!=='ready')return;if(kind==='custom')beginCustom(i);busy=true;refreshRuntime();const button=$(`#run-${kind}`);button.textContent='Running…';const code=state.investigations[i][kind].code;const output=$(`#output-${kind}`);output.classList.remove('hidden','error');output.textContent='Running your R code…';
 try{const result=await execute(code);recordResult(state.investigations[i],kind,code,result);output.textContent=state.investigations[i][kind].output;output.classList.toggle('error',result.failed);if(result.graph&&!result.failed){$(`#graph-${kind}`).innerHTML=graphMarkup(i,kind);$(`[data-revert="${kind}"]`).classList.remove('hidden');if(kind==='basic'){$('#copy-basic').disabled=false;const rect=$('#editor-custom').getBoundingClientRect();if(rect.top<innerHeight&&rect.bottom>0)beginCustom(i);}}state.workspace=result.workspace;$(`#note-${kind}`).textContent=graphNote(i,kind);save();}
 catch(e){output.classList.add('error');output.textContent='R error: '+e.message+'\nYour code and both saved graphs are still here.';state.investigations[i][kind].output=output.textContent;save();}
 finally{busy=false;button.textContent=`Run ${kind==='basic'?'Basic':'Customized'} R`;refreshRuntime();}
}
function renderFinish(){
 const fallback=state.investigations.some(item=>!item.custom.graph&&item.basic.graph),stale=state.investigations.some(item=>{const v=finalVersion(item);return v.graph&&v.code!==v.graphCode;});
 $('#main').innerHTML=`<section class="page-heading"><h1>Finish & Submit</h1></section><section class="submit-notice"><h2>You must upload your PDF to Canvas.</h2><p>Downloading your work does not submit it. You still need to open Canvas and upload the PDF yourself.</p></section><div class="finish-name"><label for="student-name">Your name</label><input id="student-name" autocomplete="name" maxlength="150" value="${escape(state.name)}" placeholder="Name for your homework PDF"></div><h2>Check your work</h2><ul class="checklist">${investigations.map((l,i)=>{const item=state.investigations[i];return `<li><strong>${l.short}:</strong> ${item.basic.graph?'✓ Basic graph saved':'Basic graph needed'} · ${item.custom.graph?'customized graph saved':item.basic.graph?'basic graph available — customization not completed; this basic graph will be exported':'customized graph needed'} · ${requiredAnswers(l).length-answerMissing(l,item.answers).length}/${requiredAnswers(l).length} questions answered</li>`;}).join('')}</ul>${fallback?'<p class="notice warning">Customization is not completed for every graph. Where no customized graph exists, your successful basic graph and its code will be used.</p>':''}${stale?'<p class="notice warning">Some editor code has changed since its graph was saved. The PDF uses the code that produced the saved graph, so it matches the PNG. Rerun your revised code if you want to include those changes.</p>':''}<section class="editorial-section"><h2>Your download contains:</h2><p><strong>Completed homework PDF — Submit this to Canvas.</strong></p><p><strong>Three PNG graph images — Keep these for your final project.</strong></p><button class="primary" id="export">Download My Homework ZIP</button><div id="export-message" role="status"></div></section><section class="editorial-section"><h2>After downloading</h2><ol class="submission-steps"><li>Find the downloaded ZIP file and extract it.</li><li>Open Canvas and upload <strong>R_You_Watching_Homework.pdf</strong>.</li><li>Keep the three PNG graph images for your final project.</li></ol><p><strong>Do not upload the PNG images to Canvas for this homework.</strong></p><p class="submit-again">Downloading is not submitting.</p></section><div class="nav-actions"><button id="back" class="secondary">← Storylines</button></div>`;
 $('#student-name').oninput=e=>{state.name=e.target.value;save();};$('#back').onclick=()=>go(4);
 $('#export').onclick=async()=>{const missing=missingFields(state);if(missing.length){$('#export-message').innerHTML=`<div class="notice warning">Before downloading, finish:<ul>${missing.map(m=>`<li>${escape(m)}</li>`).join('')}</ul></div>`;return;}const button=$('#export');button.disabled=true;busy=true;$('#export-message').textContent='Creating your PDF and packaging three graph images…';try{await flush();const blob=await makeArchive(structuredClone(state));download(blob,'R_You_Watching_Homework.zip');$('#export-message').textContent='Your ZIP was generated and the download was requested. Extract it, then upload the PDF to Canvas. Downloading is not submitting.';}catch(e){$('#export-message').textContent='We could not generate the ZIP. Your work is still here. Please try again. '+e.message;}finally{busy=false;button.disabled=false;}};
}
try{const saved=await readProgress();state=restoreState(saved);if(saved?.version===1)save();}catch{$('#save-status').textContent='Local saving is unavailable. Keep this tab open and download your work.';}
render();if(state.show)startR();
window.addEventListener('pagehide',()=>{flush();});
